import React, { useState, useRef } from 'react';
import { useNavigate, useRoutes } from 'react-router-dom';
import Meeting from '../Meeting/Meeting';
import useSocket from '../../Hooks/useSocket';
import './Lobby.css'; // Assuming you have a separate CSS for Lobby

function Lobby() {
  const [isHosting, setIsHosting] = useState(false);
  const [isJoined, setIsJoined] = useState(false);
  const [stream, setStream] = useState(null);
  const userVideo = useRef();
  const navigate = useNavigate();

  const socket = useSocket(navigate, userVideo, setStream, setIsHosting, setIsJoined);

  const handleHostMeeting = () => {
    if (socket && !isHosting) {
      socket.emit('host');
    }
  };

  const handleJoinMeeting = () => {
    if (socket && !isJoined) {
      socket.emit('join');
    }
  };

  const handleMuteUnmute = () => {
    if (stream) {
      stream.getAudioTracks()[0].enabled = !stream.getAudioTracks()[0].enabled;
    }
  };

  const handleOpenCloseCamera = (videoRef) => {
    if (videoRef.current && videoRef.current.srcObject) {
      const enabled = videoRef.current.srcObject.getVideoTracks()[0].enabled;
      videoRef.current.srcObject.getVideoTracks()[0].enabled = !enabled;
    }
  };  

  let routes = useRoutes([
    {
      path: "/",
      element: (
        <div className="Lobby">
          <main>
            {/* Lobby content */}
          </main>
        </div>
      ),
    },
    {
      path: "/meeting",
      element: <Meeting stream={stream} handleMuteUnmute={handleMuteUnmute} handleOpenCloseCamera={handleOpenCloseCamera} />,
    },
  ]);

  return routes;
}

export default Lobby;
